package com.example.turnbased.core;

import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.headless.mock.input.MockInput;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * MockInput subclass that exposes a scripted sequence of commands to the
 * game. Each call to {@link #tick()} advances the cursor by one position and
 * updates the "current command" state. While the cursor is inside the list,
 * {@link #isKeyJustPressed(int)} and {@link #isKeyPressed(int)} return true
 * for the libGDX keycode mapped from the current command. Once the cursor
 * walks past the end, both methods always return false.
 */
public class ScriptedMockInput extends MockInput {

    private List<String> commands = Collections.emptyList();
    private int cursor = -1;
    private String currentRaw;
    private int currentKey = KEY_NONE;

    /** Sentinel value for "no active key for this tick". */
    private static final int KEY_NONE = -1;

    public ScriptedMockInput() {
        super();
    }

    /** Replaces the queued commands. Safe to call before {@link #tick()}. */
    public synchronized void setCommands(List<String> commands) {
        this.commands = new ArrayList<>(commands);
        this.cursor = -1;
        this.currentRaw = null;
        this.currentKey = KEY_NONE;
    }

    /**
     * Advance to the next command in the script. When the cursor moves past
     * the last entry, the input reports no key activity for subsequent ticks.
     */
    public synchronized void tick() {
        int next = cursor + 1;
        if (next < commands.size()) {
            cursor = next;
            currentRaw = commands.get(cursor);
            currentKey = mapToKey(currentRaw);
        } else {
            currentRaw = null;
            currentKey = KEY_NONE;
        }
    }

    /** True when a command is still available for this tick. */
    public synchronized boolean hasCommand() {
        return currentRaw != null;
    }

    /** The raw command text for the current tick (null when exhausted). */
    public synchronized String currentCommand() {
        return currentRaw;
    }

    @Override
    public synchronized boolean isKeyJustPressed(int keycode) {
        return currentKey != KEY_NONE && currentKey == keycode;
    }

    @Override
    public synchronized boolean isKeyPressed(int keycode) {
        return currentKey != KEY_NONE && currentKey == keycode;
    }

    private static int mapToKey(String cmd) {
        if (cmd == null) {
            return KEY_NONE;
        }
        switch (cmd) {
            case "N":    return Input.Keys.UP;
            case "S":    return Input.Keys.DOWN;
            case "E":    return Input.Keys.RIGHT;
            case "W":    return Input.Keys.LEFT;
            case "PICK": return Input.Keys.SPACE;
            case "QUIT": return Input.Keys.ESCAPE;
            default:     return KEY_NONE;
        }
    }
}

package com.example.turnbased.core;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;

import java.util.List;
import java.util.concurrent.CountDownLatch;

/**
 * Headless {@link ApplicationListener} that drives the deterministic turn
 * loop. One command is consumed per {@link #render()} call, the world is
 * mutated accordingly, and a transcript line is buffered. When the input is
 * exhausted or a {@code QUIT} command is processed, the transcript is
 * flushed to disk and the application is asked to exit.
 */
public final class GameListener implements ApplicationListener {

    private final ScriptedMockInput input;
    private final String mapPath;
    private final String commandsPath;
    private final String transcriptPath;

    private final CountDownLatch doneLatch = new CountDownLatch(1);
    private final StringBuilder transcript = new StringBuilder();

    private World world;
    private int turnsProcessed = 0;
    private boolean exiting = false;
    private boolean finalized = false;

    public GameListener(ScriptedMockInput input,
                        String mapPath,
                        String commandsPath,
                        String transcriptPath) {
        this.input = input;
        this.mapPath = mapPath;
        this.commandsPath = commandsPath;
        this.transcriptPath = transcriptPath;
    }

    public CountDownLatch getDoneLatch() {
        return doneLatch;
    }

    @Override
    public void create() {
        // By the time create() runs, the HeadlessApplication has already
        // populated the static Gdx.* fields, so the libGDX file API is safe.
        List<String> commands = CommandsLoader.load(commandsPath);
        input.setCommands(commands);
        world = MapLoader.load(mapPath);
    }

    @Override
    public void render() {
        if (exiting) {
            return;
        }

        input.tick();

        if (!input.hasCommand()) {
            // Command file has been fully consumed without an explicit QUIT.
            finalize();
            return;
        }

        String cmd = input.currentCommand();
        applyCommand(cmd);
        turnsProcessed++;

        transcript.append("turn=").append(turnsProcessed)
                  .append(" cmd=").append(cmd)
                  .append(" pos=").append(world.playerX).append(',').append(world.playerY)
                  .append(" inv=").append(formatInventory())
                  .append('\n');

        if ("QUIT".equals(cmd)) {
            finalize();
        }
    }

    private void applyCommand(String cmd) {
        switch (cmd) {
            case "N":
                world.tryMove(0, 1);
                break;
            case "S":
                world.tryMove(0, -1);
                break;
            case "E":
                world.tryMove(1, 0);
                break;
            case "W":
                world.tryMove(-1, 0);
                break;
            case "PICK":
                world.tryPick();
                break;
            case "QUIT":
                // Marker for end-of-loop; the actual handling lives in render().
                break;
            default:
                // Unknown command: no-op, but the raw token is still recorded.
                break;
        }
    }

    private String formatInventory() {
        List<String> inv = world.getInventory();
        if (inv.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < inv.size(); i++) {
            if (i > 0) {
                sb.append(',');
            }
            sb.append(inv.get(i));
        }
        return sb.toString();
    }

    private void finalize() {
        if (finalized) {
            return;
        }
        finalized = true;
        exiting = true;

        transcript.append("FINAL pos=").append(world.playerX).append(',').append(world.playerY)
                  .append(" inv=").append(formatInventory())
                  .append(" turns=").append(turnsProcessed)
                  .append('\n');

        FileHandle fh = Gdx.files.absolute(transcriptPath);
        fh.writeString(transcript.toString(), false);

        Gdx.app.exit();
    }

    @Override
    public void pause() {
        // No-op for the headless turn loop.
    }

    @Override
    public void resume() {
        // No-op for the headless turn loop.
    }

    @Override
    public void dispose() {
        // Safety net so the launcher's main thread never blocks forever if
        // the loop exits before finalize() ever ran.
        doneLatch.countDown();
    }
}

